//! VVC integer transforms: DCT-II, DCT-VIII and DST-VII.
//!
//! The matrices are the normative ITU-T H.266 (VVC) transform matrices
//! (clause 8.6.4.2), generated by `tools/extract_transform_tables.sh` from
//! Fraunhofer HHI VVenC and cross-checked against FFmpeg by
//! `tools/verify_transform_tables.py`.
//!
//! The forward transform applies the matrix separably (rows then columns)
//! with the shift schedule from ITU-T H.266 clause 8.6.4.2:
//!
//! ```text
//! shift_1st = log2(width)  + bitDepth + TRANSFORM_MATRIX_SHIFT - maxLog2TrDynamicRange
//! shift_2nd = log2(height) + TRANSFORM_MATRIX_SHIFT
//! ```
//!
//! with `TRANSFORM_MATRIX_SHIFT = 6` and `maxLog2TrDynamicRange = 15`
//! (8-bit content). The inverse transform uses the mirrored schedule:
//!
//! ```text
//! shift_1st = TRANSFORM_MATRIX_SHIFT + 1
//! shift_2nd = TRANSFORM_MATRIX_SHIFT + maxLog2TrDynamicRange - 1 - bitDepth
//! ```

use crate::transform_tables::*;

/// The transform families in the VVC multiple-transform-selection set.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TransformKind {
    /// DCT-II, the default transform in every codec generation.
    Dct2,
    /// DCT-VIII, selected in VVC for blocks with certain characteristics.
    Dct8,
    /// DST-VII, selected in VVC for intra blocks.
    Dst7,
}

/// A VVC multiple transform selection mode.
///
/// VVC's multiple transform selection is *separable per axis*: the
/// horizontal pass and the vertical pass each choose between DCT-VIII
/// and DST-VII, giving four modes in addition to the plain DCT-II.
/// ITU-T H.266 clause 8.6.3 defines the four modes as DST-VII/DST-VII,
/// DCT-VIII/DST-VII, DST-VII/DCT-VIII and DCT-VIII/DCT-VIII.
///
/// GIRC codes that mode rather than a single transform applied to both
/// axes, because the mode is what a VVC decoder actually has to be told.
/// Signalling a single matrix would measure a mechanism that does not
/// exist in the standard.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct TransformMode {
    /// The transform applied in the horizontal pass.
    pub horizontal: TransformKind,
    /// The transform applied in the vertical pass.
    pub vertical: TransformKind,
}

impl TransformMode {
    /// The plain DCT-II mode, which is not a multiple transform selection
    /// mode at all.
    pub const DCT2: TransformMode = TransformMode {
        horizontal: TransformKind::Dct2,
        vertical: TransformKind::Dct2,
    };

    /// The four multiple transform selection modes, in the order ITU-T
    /// H.266 numbers them.
    pub const MTS: [TransformMode; 4] = [
        TransformMode {
            horizontal: TransformKind::Dst7,
            vertical: TransformKind::Dst7,
        },
        TransformMode {
            horizontal: TransformKind::Dct8,
            vertical: TransformKind::Dst7,
        },
        TransformMode {
            horizontal: TransformKind::Dst7,
            vertical: TransformKind::Dct8,
        },
        TransformMode {
            horizontal: TransformKind::Dct8,
            vertical: TransformKind::Dct8,
        },
    ];

    /// Every mode, the plain DCT-II first, in canonical order.
    pub const ALL: [TransformMode; 5] = [
        TransformMode::DCT2,
        TransformMode::MTS[0],
        TransformMode::MTS[1],
        TransformMode::MTS[2],
        TransformMode::MTS[3],
    ];

    /// The index of the mode, as it appears on the wire.
    ///
    /// The indices are the ones ITU-T H.266 uses: zero for the plain
    /// DCT-II, then the four multiple transform selection modes in the
    /// standard's order.
    pub fn as_index(self) -> u8 {
        if self == TransformMode::DCT2 {
            return 0;
        }
        match (self.horizontal, self.vertical) {
            (TransformKind::Dst7, TransformKind::Dst7) => 1,
            (TransformKind::Dct8, TransformKind::Dst7) => 2,
            (TransformKind::Dst7, TransformKind::Dct8) => 3,
            (TransformKind::Dct8, TransformKind::Dct8) => 4,
            _ => unreachable!("the mode set is closed"),
        }
    }

    /// The inverse of [`TransformMode::as_index`].
    pub fn from_index(index: u8) -> Option<Self> {
        Self::ALL.get(index as usize).copied()
    }

    /// A readable name, in the standard's terms.
    pub fn name(self) -> String {
        if self == TransformMode::DCT2 {
            return "DCT-II".to_string();
        }
        format!("{}/{}", self.horizontal.name(), self.vertical.name())
    }

    /// Whether the mode is one of the multiple transform selection modes.
    pub fn is_mts(self) -> bool {
        self != TransformMode::DCT2
    }
}

impl TransformKind {
    /// Every transform in the set, in canonical order.
    pub const ALL: [TransformKind; 3] = [
        TransformKind::Dct2,
        TransformKind::Dct8,
        TransformKind::Dst7,
    ];

    /// The transform type index as it appears on the wire.
    pub fn as_index(self) -> u8 {
        match self {
            TransformKind::Dct2 => 0,
            TransformKind::Dct8 => 1,
            TransformKind::Dst7 => 2,
        }
    }

    /// Inverse of [`TransformKind::as_index`].
    pub fn from_index(index: u8) -> Option<Self> {
        match index {
            0 => Some(TransformKind::Dct2),
            1 => Some(TransformKind::Dct8),
            2 => Some(TransformKind::Dst7),
            _ => None,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            TransformKind::Dct2 => "DCT-II",
            TransformKind::Dct8 => "DCT-VIII",
            TransformKind::Dst7 => "DST-VII",
        }
    }

    /// The integer matrix for this transform at the given size.
    ///
    /// Sizes outside the VVC transform set (4, 8, 16, 32) have no matrix.
    /// The matrix is returned flattened in row-major order.
    pub fn matrix(self, size: usize) -> Option<&'static [i32]> {
        // The generated tables are per-size statics of differing row widths;
        // each coerces to a flat slice.
        match (self, size) {
            (TransformKind::Dct2, 4) => Some(&DCT24),
            (TransformKind::Dct2, 8) => Some(&DCT28),
            (TransformKind::Dct2, 16) => Some(&DCT216),
            (TransformKind::Dct2, 32) => Some(&DCT232),
            (TransformKind::Dct8, 4) => Some(&DCT84),
            (TransformKind::Dct8, 8) => Some(&DCT88),
            (TransformKind::Dct8, 16) => Some(&DCT816),
            (TransformKind::Dct8, 32) => Some(&DCT832),
            (TransformKind::Dst7, 4) => Some(&DST74),
            (TransformKind::Dst7, 8) => Some(&DST78),
            (TransformKind::Dst7, 16) => Some(&DST716),
            (TransformKind::Dst7, 32) => Some(&DST732),
            _ => None,
        }
    }
}

/// Bit depth of the samples the transform operates on.
pub const BIT_DEPTH: u32 = 8;
/// `maxLog2TrDynamicRange` for 8-bit content, ITU-T H.266 clause 8.6.4.
pub const MAX_LOG2_TR_DYNAMIC_RANGE: u32 = 15;
/// `TRANSFORM_MATRIX_SHIFT`, ITU-T H.266 clause 8.6.4.
pub const TRANSFORM_MATRIX_SHIFT: u32 = 6;

/// Maximum transform block size supported by the VVC transform set.
pub const MAX_TU_SIZE: usize = 32;

/// A square block of transform coefficients.
pub type Block = Vec<i32>;

/// Errors produced by the transform.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TransformError {
    /// The requested block size has no matrix in the VVC transform set.
    UnsupportedSize { kind: TransformKind, size: usize },
    /// The block length does not match the declared size.
    LengthMismatch { expected: usize, got: usize },
}

impl std::fmt::Display for TransformError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TransformError::UnsupportedSize { kind, size } => {
                write!(
                    f,
                    "{} has no {size}x{size} matrix in the VVC transform set",
                    kind.name()
                )
            }
            TransformError::LengthMismatch { expected, got } => {
                write!(
                    f,
                    "block length {got} does not match declared size {expected}"
                )
            }
        }
    }
}

impl std::error::Error for TransformError {}

/// Forward 2-D transform of a `size` x `size` block.
///
/// The input and output are in raster order. The result is the VVC
/// transform-coefficient domain, ready for quantization.
pub fn forward(kind: TransformKind, size: usize, block: &[i32]) -> Result<Block, TransformError> {
    let matrix = kind
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize { kind, size })?;
    if block.len() != size * size {
        return Err(TransformError::LengthMismatch {
            expected: size * size,
            got: block.len(),
        });
    }

    let shift_1st =
        size.trailing_zeros() + BIT_DEPTH + TRANSFORM_MATRIX_SHIFT - MAX_LOG2_TR_DYNAMIC_RANGE;
    let shift_2nd = size.trailing_zeros() + TRANSFORM_MATRIX_SHIFT;

    // Pass 1: horizontal. `tmp[y][x]` holds the partially transformed value.
    let mut tmp = vec![0i32; size * size];
    for y in 0..size {
        for x in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(matrix[x * size + k]) * i64::from(block[y * size + k]);
            }
            tmp[y * size + x] = round_shift(sum, shift_1st);
        }
    }

    // Pass 2: vertical.
    let mut out = vec![0i32; size * size];
    for x in 0..size {
        for y in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(matrix[y * size + k]) * i64::from(tmp[k * size + x]);
            }
            out[y * size + x] = round_shift(sum, shift_2nd);
        }
    }
    Ok(out)
}

/// The 2-D forward transform of a multiple transform selection mode.
///
/// The two passes use different matrices, which is what distinguishes a
/// multiple transform selection mode from a plain transform. The shift
/// schedule is the one in ITU-T H.266 clause 8.6.4.2, the same one
/// [`forward`] uses:
///
/// ```text
/// shift_1st = log2(width)  + bitDepth + TRANSFORM_MATRIX_SHIFT - maxLog2TrDynamicRange
/// shift_2nd = log2(height) + TRANSFORM_MATRIX_SHIFT
/// ```
pub fn forward_mode(
    mode: TransformMode,
    size: usize,
    block: &[i32],
) -> Result<Block, TransformError> {
    let horizontal = mode
        .horizontal
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize {
            kind: mode.horizontal,
            size,
        })?;
    let vertical = mode
        .vertical
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize {
            kind: mode.vertical,
            size,
        })?;
    if block.len() != size * size {
        return Err(TransformError::LengthMismatch {
            expected: size * size,
            got: block.len(),
        });
    }

    let shift_1st =
        size.trailing_zeros() + BIT_DEPTH + TRANSFORM_MATRIX_SHIFT - MAX_LOG2_TR_DYNAMIC_RANGE;
    let shift_2nd = size.trailing_zeros() + TRANSFORM_MATRIX_SHIFT;

    // Pass 1: horizontal, with the horizontal matrix.
    let mut tmp = vec![0i32; size * size];
    for y in 0..size {
        for x in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(horizontal[x * size + k]) * i64::from(block[y * size + k]);
            }
            tmp[y * size + x] = round_shift(sum, shift_1st);
        }
    }

    // Pass 2: vertical, with the vertical matrix.
    let mut out = vec![0i32; size * size];
    for x in 0..size {
        for y in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(vertical[y * size + k]) * i64::from(tmp[k * size + x]);
            }
            out[y * size + x] = round_shift(sum, shift_2nd);
        }
    }
    Ok(out)
}

/// The 2-D inverse transform of a multiple transform selection mode.
///
/// The inverse runs the vertical pass first, then the horizontal pass,
/// which is the reverse of [`forward_mode`] and matches the schedule in
/// ITU-T H.266 clause 8.6.4.2.
pub fn inverse_mode(
    mode: TransformMode,
    size: usize,
    coeffs: &[i32],
) -> Result<Block, TransformError> {
    let horizontal = mode
        .horizontal
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize {
            kind: mode.horizontal,
            size,
        })?;
    let vertical = mode
        .vertical
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize {
            kind: mode.vertical,
            size,
        })?;
    if coeffs.len() != size * size {
        return Err(TransformError::LengthMismatch {
            expected: size * size,
            got: coeffs.len(),
        });
    }

    let shift_1st = TRANSFORM_MATRIX_SHIFT + 1;
    let shift_2nd = TRANSFORM_MATRIX_SHIFT + MAX_LOG2_TR_DYNAMIC_RANGE - 1 - BIT_DEPTH;

    // Pass 1: vertical, into `tmp`. The inverse transform transposes the
    // matrix, which is why the index is `k * size + y` rather than
    // `y * size + k`.
    let mut tmp = vec![0i32; size * size];
    for x in 0..size {
        for y in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(vertical[k * size + y]) * i64::from(coeffs[k * size + x]);
            }
            tmp[y * size + x] = round_shift(sum, shift_1st);
        }
    }

    // Pass 2: horizontal.
    let mut out = vec![0i32; size * size];
    for y in 0..size {
        for x in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(horizontal[k * size + x]) * i64::from(tmp[y * size + k]);
            }
            out[y * size + x] = round_shift(sum, shift_2nd);
        }
    }
    Ok(out)
}

/// Inverse 2-D transform of a `size` x `size` coefficient block.
///
/// The result is in the sample domain, before the final clipping the decoder
/// applies to the reconstructed sample.
pub fn inverse(kind: TransformKind, size: usize, coeffs: &[i32]) -> Result<Block, TransformError> {
    let matrix = kind
        .matrix(size)
        .ok_or(TransformError::UnsupportedSize { kind, size })?;
    if coeffs.len() != size * size {
        return Err(TransformError::LengthMismatch {
            expected: size * size,
            got: coeffs.len(),
        });
    }

    let shift_1st = TRANSFORM_MATRIX_SHIFT + 1;
    let shift_2nd = TRANSFORM_MATRIX_SHIFT + MAX_LOG2_TR_DYNAMIC_RANGE - 1 - BIT_DEPTH;

    // Pass 1: vertical, into `tmp`.
    let mut tmp = vec![0i32; size * size];
    for x in 0..size {
        for y in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(matrix[k * size + y]) * i64::from(coeffs[k * size + x]);
            }
            tmp[y * size + x] = round_shift(sum, shift_1st);
        }
    }

    // Pass 2: horizontal, into the sample domain.
    let mut out = vec![0i32; size * size];
    for y in 0..size {
        for x in 0..size {
            let mut sum = 0i64;
            for k in 0..size {
                sum += i64::from(matrix[k * size + x]) * i64::from(tmp[y * size + k]);
            }
            out[y * size + x] = round_shift(sum, shift_2nd);
        }
    }
    Ok(out)
}

/// Arithmetic right shift with round-to-nearest, matching the reference
/// software's `(value + add) >> shift` with `add = 1 << (shift - 1)`.
fn round_shift(value: i64, shift: u32) -> i32 {
    if shift == 0 {
        return value as i32;
    }
    let add = 1i64 << (shift - 1);
    ((value + add) >> shift) as i32
}

/// The transform sizes in the VVC set.
pub const TRANSFORM_SIZES: [usize; 4] = [4, 8, 16, 32];

#[cfg(test)]
mod tests {
    use super::*;
    use crate::transform_oracle_vectors::{ORACLE_MODE_VECTORS, ORACLE_VECTORS};

    /// The forward and inverse transforms must match the VVC reference
    /// implementation bit-exactly. The reference vectors come from Fraunhofer
    /// HHI's own transform kernels (`tools/transform_oracle.c`).
    #[test]
    fn matches_vvc_reference_implementation() {
        assert!(!ORACLE_VECTORS.is_empty(), "reference vectors are present");
        for vector in ORACLE_VECTORS {
            let kind = TransformKind::ALL[vector.kind];
            let size = vector.size;

            let forward = forward(kind, size, vector.input)
                .unwrap_or_else(|e| panic!("{kind:?} {size}: forward failed: {e}"));
            assert_eq!(
                forward, vector.forward,
                "{kind:?} {size}x{size}: forward transform differs from the reference"
            );

            let inverse = inverse(kind, size, vector.forward)
                .unwrap_or_else(|e| panic!("{kind:?} {size}: inverse failed: {e}"));
            assert_eq!(
                inverse, vector.inverse,
                "{kind:?} {size}x{size}: inverse transform differs from the reference"
            );
        }
    }

    /// The per-axis multiple transform selection modes must match the VVC
    /// reference implementation bit-exactly.
    ///
    /// These are the transforms a VVC decoder actually has to be told
    /// about, and they are the ones the mechanism's signalling replaces.
    #[test]
    fn modes_match_vvc_reference_implementation() {
        assert!(
            !ORACLE_MODE_VECTORS.is_empty(),
            "reference mode vectors are present"
        );
        for vector in ORACLE_MODE_VECTORS {
            let mode = TransformMode {
                horizontal: TransformKind::ALL[vector.horizontal],
                vertical: TransformKind::ALL[vector.vertical],
            };
            let size = vector.size;

            let forward = forward_mode(mode, size, vector.input)
                .unwrap_or_else(|e| panic!("{} {size}: forward failed: {e}", mode.name()));
            assert_eq!(
                forward,
                vector.forward,
                "{} {size}x{size}: forward transform differs from the reference",
                mode.name()
            );

            let inverse = inverse_mode(mode, size, vector.forward)
                .unwrap_or_else(|e| panic!("{} {size}: inverse failed: {e}", mode.name()));
            assert_eq!(
                inverse,
                vector.inverse,
                "{} {size}x{size}: inverse transform differs from the reference",
                mode.name()
            );
        }
    }

    /// The four multiple transform selection modes are the ones the
    /// standard defines, and their indices are stable.
    #[test]
    fn mode_indices_match_the_standard() {
        for (index, mode) in TransformMode::ALL.iter().enumerate() {
            assert_eq!(mode.as_index() as usize, index);
            assert_eq!(TransformMode::from_index(index as u8), Some(*mode));
        }
        // The plain DCT-II is not a multiple transform selection mode.
        assert!(!TransformMode::DCT2.is_mts());
        for mode in TransformMode::MTS {
            assert!(mode.is_mts());
            assert_ne!(mode.horizontal, TransformKind::Dct2);
            assert_ne!(mode.vertical, TransformKind::Dct2);
        }
    }

    /// Every matrix must be square with the declared size.
    #[test]
    fn matrices_have_expected_shape() {
        for kind in TransformKind::ALL {
            for size in TRANSFORM_SIZES {
                let m = kind.matrix(size).expect("size is in the VVC set");
                assert_eq!(m.len(), size * size, "matrix is flattened row-major");
            }
        }
    }

    /// The VVC transform matrices are orthogonal up to their scale factor, so
    /// `M * M^T` is a scaled identity. That is a strong check that the tables
    /// were not corrupted in generation.
    #[test]
    fn matrices_are_orthogonal_up_to_scale() {
        for kind in TransformKind::ALL {
            for size in TRANSFORM_SIZES {
                let m = kind.matrix(size).unwrap();
                // M * M^T is a scaled identity up to the rounding error
                // inherent in the standard's integer tables.
                let mut diag = 0i64;
                for k in 0..size {
                    diag += i64::from(m[k * size]) * i64::from(m[k * size]);
                }
                assert!(diag > 0, "{kind:?} {size}x{size}: M*M^T diagonal");
                for i in 0..size {
                    for j in 0..size {
                        if i == j {
                            continue;
                        }
                        let mut acc = 0i64;
                        for k in 0..size {
                            acc += i64::from(m[k * size + i]) * i64::from(m[k * size + j]);
                        }
                        // The residue is a rounding artefact, so compare it
                        // against the diagonal magnitude rather than zero.
                        let residue = acc.abs() as f64 / diag as f64;
                        assert!(
                            residue < 5e-3,
                            "{kind:?} {size}x{size}: M*M^T off-diagonal residue {residue}"
                        );
                    }
                }
            }
        }
    }

    /// A round trip through the transform must reconstruct the input to
    /// within the precision the VVC shift schedule allows.
    #[test]
    fn round_trip_reconstructs_input() {
        let size = 8;
        let mut block = vec![0i32; size * size];
        let mut state = 0x1234_5678u32;
        for v in block.iter_mut() {
            state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            *v = (state >> 24) as i32 % 64 - 32;
        }
        for kind in TransformKind::ALL {
            let coeffs = forward(kind, size, &block).unwrap();
            let recon = inverse(kind, size, &coeffs).unwrap();
            for (orig, got) in block.iter().zip(recon.iter()) {
                assert!(
                    (orig - got).abs() <= 4,
                    "{kind:?}: {orig} vs {got} (max abs error too large)"
                );
            }
        }
    }

    /// The transform of a constant block must put all energy in the DC
    /// coefficient. Only DCT-II has a constant first row; DCT-VIII and
    /// DST-VII are not constant-row transforms, so the property is specific
    /// to DCT-II.
    #[test]
    fn constant_block_is_pure_dc_for_dct2() {
        let size = 4;
        let block = vec![100i32; size * size];
        let coeffs = forward(TransformKind::Dct2, size, &block).unwrap();
        for (i, c) in coeffs.iter().enumerate() {
            if i != 0 {
                assert_eq!(*c, 0, "DCT-II: non-DC coefficient {i} is {c}");
            }
        }
        assert!(coeffs[0] > 0, "DCT-II: DC coefficient is negative");
    }

    /// DCT-VIII and DST-VII are not constant-row transforms, so a constant
    /// block spreads energy across several coefficients. This pins the
    /// difference so a mix-up between the two transform families is caught.
    #[test]
    fn constant_block_is_not_pure_dc_for_dct8_and_dst7() {
        let size = 4;
        let block = vec![100i32; size * size];
        for kind in [TransformKind::Dct8, TransformKind::Dst7] {
            let coeffs = forward(kind, size, &block).unwrap();
            assert!(
                coeffs[1..].iter().any(|c| *c != 0),
                "{kind:?}: expected non-DC energy for a constant block"
            );
        }
    }
}
